public class InnerSubscriberEventBusV2ParametersFactory(Action<Humidifier.EventsV2.SubscriberTypes.EventBusV2Parameters> factoryAction = null) : SubResourceFactory<Humidifier.EventsV2.SubscriberTypes.EventBusV2Parameters>
{

    internal InnerSubscriberEventBusV2SystemMetadataFactory SystemMetadataFactory { get; set; }

    internal InnerSubscriberDeduplicationConfigurationFactory DeduplicationConfigurationFactory { get; set; }

    protected override Humidifier.EventsV2.SubscriberTypes.EventBusV2Parameters Create()
    {
        var eventBusV2ParametersResult = CreateEventBusV2Parameters();
        factoryAction?.Invoke(eventBusV2ParametersResult);

        return eventBusV2ParametersResult;
    }

    private Humidifier.EventsV2.SubscriberTypes.EventBusV2Parameters CreateEventBusV2Parameters()
    {
        var eventBusV2ParametersResult = new Humidifier.EventsV2.SubscriberTypes.EventBusV2Parameters();

        return eventBusV2ParametersResult;
    }
    public override void CreateChildren(Humidifier.EventsV2.SubscriberTypes.EventBusV2Parameters result)
    {
        base.CreateChildren(result);

        result.SystemMetadata ??= SystemMetadataFactory?.Build();
        result.DeduplicationConfiguration ??= DeduplicationConfigurationFactory?.Build();
    }

} // End Of Class

